<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  :root {
    --bg: #1a1a2e;
    --board-bg: #16213e;
    --cell-bg: #2a2a4a;
    --text: #eee;
    --accent: #e94560;
  }
