</head>
<body>
  <h1>2048</h1>
  <div class="header">
    <div class="score-box"><span class="label">Score</span><span id="score">0</span></div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>
  <div class="help">Use the arrow keys to move tiles. Merge equal numbers to reach 2048.</div>

<script>
(function () {
  "use strict";

  const SIZE = 4;
  let grid = [];
  let scoreVal = 0;

  function emptyGrid() {
    const g = [];
    for (let i = 0; i < SIZE; i++) g.push(new Array(SIZE).fill(0));
    return g;
  }

  function copyBoard(b) {
    return b.map(function (r) { return r.slice(); });
  }

  function boardsEqual(a, b) {
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        if (a[i][j] !== b[i][j]) return false;
      }
    }
    return true;
  }

  // Slide a single row to the left; merge pairs at most once.
  function slideLeftRow(row) {
    const nonZero = row.filter(function (x) { return x !== 0; });
    const result = [];
    let gained = 0;
    let i = 0;
    while (i < nonZero.length) {
      if (i + 1 < nonZero.length && nonZero[i] === nonZero[i + 1]) {
        const merged = nonZero[i] * 2;
        result.push(merged);
        gained += merged;
        i += 2;
      } else {
        result.push(nonZero[i]);
        i += 1;
      }
    }
    while (result.length < SIZE) result.push(0);
    return { row: result, gained: gained };
  }

  function moveLeft(b) {
    let gained = 0;
    const out = b.map(function (row) {
      const r = slideLeftRow(row);
      gained += r.gained;
      return r.row;
    });
    return { board: out, gained: gained };
  }

  function reverseRows(b) {
    return b.map(function (r) { return r.slice().reverse(); });
  }

  function transpose(b) {
    const t = emptyGrid();
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        t[j][i] = b[i][j];
      }
    }
    return t;
  }

  function applyMove(b, dir) {
    if (dir === "left") {
      return moveLeft(b);
    }
    if (dir === "right") {
      const r = moveLeft(reverseRows(b));
      return { board: reverseRows(r.board), gained: r.gained };
    }
    if (dir === "up") {
      const r = moveLeft(transpose(b));
      return { board: transpose(r.board), gained: r.gained };
    }
    if (dir === "down") {
      const r = moveLeft(reverseRows(transpose(b)));
      return { board: transpose(reverseRows(r.board)), gained: r.gained };
    }
    return { board: copyBoard(b), gained: 0 };
  }

  function emptyCells(b) {
    const cells = [];
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        if (b[i][j] === 0) cells.push([i, j]);
      }
    }
    return cells;
  }

  function spawnTile(b) {
    const cells = emptyCells(b);
    if (cells.length === 0) return false;
    const pick = cells[Math.floor(Math.random() * cells.length)];
    b[pick[0]][pick[1]] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function render() {
    const boardEl = document.getElementById("board");
    boardEl.innerHTML = "";
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        const v = grid[i][j];
        const cell = document.createElement("div");
        cell.className = "cell";
        if (v !== 0) {
          cell.textContent = String(v);
          cell.dataset.v = String(v);
        }
        boardEl.appendChild(cell);
      }
    }
    document.getElementById("score").textContent = String(scoreVal);
  }

  function reset() {
    grid = emptyGrid();
    scoreVal = 0;
    spawnTile(grid);
    spawnTile(grid);
    render();
  }

  function move(dir) {
    const result = applyMove(grid, dir);
    const changed = !boardsEqual(grid, result.board);
    if (changed) {
      grid = result.board;
      scoreVal += result.gained;
      spawnTile(grid);
      render();
    }
    return changed;
  }

  function board() {
    return copyBoard(grid);
  }

  function setBoard(arr) {
    // Set the grid exactly (no spawn). Reset score for deterministic grading.
    grid = arr.map(function (r) { return r.slice(); });
    scoreVal = 0;
    render();
  }

  function score() {
    return scoreVal;
  }

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: board,
    setBoard: setBoard,
    score: score,
  };

  document.getElementById("reset").addEventListener("click", function () {
    reset();
  });

  document.addEventListener("keydown", function (e) {
    const map = {
      ArrowLeft: "left",
      ArrowRight: "right",
      ArrowUp: "up",
      ArrowDown: "down",
    };
    if (Object.prototype.hasOwnProperty.call(map, e.key)) {
      e.preventDefault();
      move(map[e.key]);
    }
  });

  reset();
})();
</script>
</body>
</html>
